// ConfirmationsService calls the confirmations endpoints. Reach it as client.Confirmations. Its
// methods are Get, Confirm and Cancel.
type ConfirmationsService struct {
	client *Client
}

// Get retrieves a confirmation.
//
// See what a confirmation code stands for and how far it has got: pending, executing, completed,
// failed, expired or cancelled.
//
// Connected apps only. Confirmations belong to the app that staged them. A partner credential never
// has one, and gets CONFIRMATION_NOT_FOUND.
//
// GET /confirmations/{code}.
func (s *ConfirmationsService) Get(ctx context.Context, code string) (*Confirmation, error) {
	urlPath, err := expandPath("/confirmations/{code}", "code", code)
	if err != nil {
		return nil, err
	}
	return getOne[Confirmation](ctx, s.client, endpoint{method: http.MethodGet, path: urlPath, key: "confirmation"})
}

// Confirm confirms an instruction.
//
// Carry out an instruction a connected app staged. Only the same app, for the same customer and
// market, can confirm it.
//
// Only after the customer says yes. This is the call that trades with the customer’s money or wine.
// Show them preview.summary and confirm only on their explicit yes.
//
// POST /confirmations/{code}.
//
// The result is an ActionResult whose Value is the action's typed result: *InbondWarehouseResult
// for inbond_warehouse.suggest; *BidResult for bid.place, bid.update, bid.cancel and bid.renew;
// *OfferResult for offer.list and offer.update; *OfferRemoveResult for offer.remove; *BuyResult for
// bid.buy; *SellResult for offer.sell; *InbondAddressResult for inbond_address.add and
// inbond_address.remove; and *InstructionResult for an action this SDK does not know.
func (s *ConfirmationsService) Confirm(ctx context.Context, code string) (*Write[ActionResult], error) {
	urlPath, err := expandPath("/confirmations/{code}", "code", code)
	if err != nil {
		return nil, err
	}
	return doConfirm(ctx, s.client, endpoint{method: http.MethodPost, path: urlPath, body: emptyObject})
}

// Cancel discards an instruction.
//
// Withdraw a pending instruction before it is confirmed. It answers 204 with no body, and the code
// cannot be used again.
//
// DELETE /confirmations/{code}.
func (s *ConfirmationsService) Cancel(ctx context.Context, code string) error {
	urlPath, err := expandPath("/confirmations/{code}", "code", code)
	if err != nil {
		return err
	}
	return doEmpty(ctx, s.client, endpoint{method: http.MethodDelete, path: urlPath})
}
